import {createOrderPhotos} from './order-photos.js';
import {localNow,toIsoPeru} from './date-time-picker.js';
export function paymentContext(localDate,shift,role){const occurred=toIsoPeru(localDate),opened=shift?Math.floor(Date.parse(shift.opened_at)/60000)*60000:null,historical=!shift||Date.parse(occurred)<opened;if(!shift&&role!=='admin')throw Error('Abre el turno de esta tienda para registrar el adelanto.');if(historical&&role!=='admin')throw Error('Un administrador debe registrar los adelantos anteriores al turno.');return {occurred,historical};}
export function createOrderExperience(ctx){
 const {db,h,dialogs,dates,notice}=ctx,{esc,money,date,field,text,qtyInput,select,products,confirmCount,table,row}=h;
 const state=()=>ctx.state(),local=value=>value?new Date(new Date(value).getTime()-18000000).toISOString().slice(0,16):localNow();
 const photos=createOrderPhotos({db,root:document.querySelector('#app'),state,esc,notice});let generation=0,openOrder=null,openPanel='data';
 const paid=id=>Number(state().data.balances.find(b=>b.order_id===id)?.paid||0),balance=o=>(o.status==='cancelled'?0:Number(o.total))-paid(o.id);
 function dateField(name,label,value='',required=true){return field(label,`<input name="${name}" type="datetime-local" value="${esc(value)}" ${required?'required':''}>`);}
 function orderFields(o){return `<div class="fields">${field('Cliente',`<input name="customer_name" required value="${esc(o?.customer_name||'')}">`)}${field('Teléfono',`<input name="customer_phone" type="tel" value="${esc(o?.customer_phone||'')}">`)}${dateField('due_at','Entrega del pedido',o?local(o.due_at):'')}${field('Precio final (S/)',qtyInput('total',o?.total||0,'.01'))}</div>${field('Descripción y diseño',`<textarea name="description" required placeholder="Sabor, tamaño, dedicatoria y detalles del diseño">${esc(o?.description||'')}</textarea>`)}`;}
 function newForm(){return `<form data-form="new_order">${field('Código del pedido',`<input name="code" maxlength="80" autocomplete="off" required placeholder="Código del contrato o pedido">`)}${orderFields()}${photos.markup('new')}<h3>Adelanto inicial</h3><div class="fields">${field('Efectivo (S/)',qtyInput('advance_cash',0,'.01'))}${field('Yape (S/)',qtyInput('advance_yape',0,'.01'))}${dateField('payment_date','Fecha y hora del adelanto',localNow())}</div><p class="order-payment-context small" data-payment-context hidden></p><button>Guardar pedido</button></form>`;}
 function openNew(){dialogs.open({key:'new-order',title:'Nuevo pedido',body:newForm(),wide:true,onClose:()=>photos.drop('new')});ctx.detailReady?.();dates.mount(dialogs.element);photos.mount(dialogs.element);contextLabels();}
 function orders(){const {data}=state(),filters=ctx.filters();return `<div class="card order-page"><div class="order-page-heading"><h2>Agenda de pedidos</h2><button type="button" data-order-new>+ Nuevo pedido</button></div><div class="filters">${field('Cliente, código o teléfono',`<input data-filter="order" value="${esc(filters.order)}">`)}${field('Estado',`<select data-filter="status">${[['pending','Pendientes'],['delivered','Entregados'],['cancelled','Eliminados'],['all','Todos']].map(([id,label])=>`<option value="${id}" ${filters.status===id?'selected':''}>${label}</option>`).join('')}</select>`)}${field('Tienda',`<select data-filter="order-store"><option value="all">Ambas tiendas</option>${data.stores.map(s=>`<option value="${s.id}" ${filters.store===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select>`)}</div><div id="order-list">${data.orders.map(o=>`<div class="listitem" data-order-row="${o.id}" data-status="${o.status}" data-store="${o.store_id}" data-search="${esc(String(`${o.code} ${o.customer_name} ${o.customer_phone} ${o.description}`).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase())}"><strong>${esc(o.code)} · ${esc(o.customer_name)}</strong><p class="order-description-preview">${esc(o.description)}</p><p class="small">${date(o.due_at)} · ${esc(data.stores.find(s=>s.id===o.store_id)?.name)} · ${o.status==='pending'?'Pendiente':o.status==='delivered'?'Entregado':'Eliminado'}</p><p>Total ${money(o.total)} · <strong>${balance(o)<0?'Crédito':'Saldo'} ${money(Math.abs(balance(o)))}</strong></p><button type="button" class="secondary" data-order-detail="${o.id}">Ver pedido</button></div>`).join('')}</div><p id="order-empty" hidden class="empty">No hay pedidos con esos filtros.</p></div>`;}

 function body(o,events,past,payments){const {me,shift}=state(),pending=o.status==='pending';
  const dataPanel=pending?`<form data-form="edit_order" data-id="${o.id}" data-version="${o.version}">${orderFields(o)}${field('Motivo del cambio',text('reason'))}<button>Guardar cambios</button></form>${(me.role==='admin'||me.role==='manager'&&state().accessibleStores?.some(s=>s.id===o.store_id))?`<details class="order-cancel"><summary>Eliminar pedido</summary><form data-form="cancel_order" data-id="${o.id}" data-version="${o.version}">${field('Motivo',text('reason'))}${confirmCount('Eliminar de los pendientes y conservar pagos e historial.')}<button class="danger">Eliminar pedido</button></form></details>`:''}`:`<dl class="order-summary"><dt>Cliente</dt><dd>${esc(o.customer_name)}</dd><dt>Teléfono</dt><dd>${esc(o.customer_phone)}</dd><dt>Entrega</dt><dd>${date(o.due_at)}</dd><dt>Descripción</dt><dd>${esc(o.description)}</dd></dl>`;
  const paymentPanel=`${o.status!=='cancelled'?`<h3>Registrar adelanto o pago</h3><form data-form="order_payment" data-id="${o.id}"><div class="fields">${field('Monto (S/)',qtyInput('amount',Math.max(0,balance(o)),'.01','.01'))}${field('Medio',select('method',[['cash','Efectivo'],['yape','Yape']]))}${dateField('occurred_at','Fecha y hora del pago',localNow())}</div><p class="order-payment-context small" data-payment-context hidden></p><button>Registrar pago</button></form>`:''}${balance(o)<0&&me.role!=='worker'?`<h3>Devolver crédito</h3><form data-form="order_refund" data-id="${o.id}">${field('Monto devuelto (S/)',qtyInput('amount',-balance(o),'.01','.01'))}${field('Medio',select('method',[['cash','Efectivo'],['yape','Yape']]))}${field('Motivo',text('reason'))}${confirmCount('Confirmo que devolví el dinero al cliente.')}<button>Registrar devolución</button></form>`:''}<h3>Pagos registrados</h3>${table(['Fecha','Movimiento','Medio','Monto'],[...payments.map(p=>row([date(p.occurred_at),p.kind==='order_refund'?'Devolución':'Cobro en turno',esc(p.method),money(p.amount)])),...past.map(p=>row([date(p.occurred_at),'Adelanto anterior',esc(p.method),money(p.amount)]))])}`;
  const photoPanel=`${pending?`<form data-form="upload_photos" data-id="${o.id}">${photos.markup(o.id)}<button data-photo-save disabled>Guardar fotos pendientes</button></form>`:''}<div class="photos" data-order-saved-photos></div>`;
  const historyPanel=table(['Fecha','Acción','Motivo'],events.map(e=>row([date(e.created_at),esc({created:'Creado',edit_order:'Modificado',cancel_order:'Eliminado',order_payment:'Pago',historical_advance:'Adelanto anterior',order_refund:'Devolución',deliver_order:'Entregado'}[e.action]||e.action),`${esc(e.reason)}${e.action==='edit_order'?`<br><small>Precio ${money(e.before_data?.total)} → ${money(e.after_data?.total)}</small>`:''}`])));
  const deliveryPanel=pending&&balance(o)<=0&&shift?`<form data-form="deliver_order" data-id="${o.id}">${field('Producto de inventario (opcional)',products('product_id',()=>true,true))}${field('Cantidad',qtyInput('qty',1,'1','1'))}${confirmCount('El cliente recibió el pedido.')}<button>Confirmar entrega</button></form>`:`<p class="warn">${balance(o)>0?'Primero cobra el saldo pendiente.':!shift?'Abre el turno de la tienda que entrega.':'El pedido ya no está pendiente.'}</p><button type="button" class="secondary" data-order-panel="payments">Ir a cobros</button>`;
  return `<div class="order-detail-metrics"><div><small>Total</small><strong>${money(o.total)}</strong></div><div><small>Adelantos</small><strong>${money(paid(o.id))}</strong></div><div><small>${balance(o)<0?'Crédito':'Saldo'}</small><strong>${money(Math.abs(balance(o)))}</strong></div></div><nav class="order-detail-tabs" aria-label="Secciones del pedido">${[['data','Datos'],['payments','Cobros'],['photos','Fotos'],['history','Historial'],...(pending?[['delivery','Entregar']]:[])].map(([id,label])=>`<button type="button" data-order-panel="${id}">${label}</button>`).join('')}</nav>${[['data',dataPanel],['payments',paymentPanel],['photos',photoPanel],['history',historyPanel],['delivery',deliveryPanel]].map(([id,html])=>`<section data-order-pane="${id}" hidden>${html}</section>`).join('')}`;
 }
 function selectPanel(panel){const el=dialogs.element;if(!el||!dialogs.is('order'))return;openPanel=panel;el.querySelectorAll('[data-order-pane]').forEach(x=>x.hidden=x.dataset.orderPane!==panel);el.querySelectorAll('[data-order-panel]').forEach(b=>{b.classList.toggle('selected',b.dataset.orderPanel===panel);b.setAttribute('aria-pressed',String(b.dataset.orderPanel===panel));});}
 async function detail(id,panel='data'){const {data,user}=state(),o=data.orders.find(o=>o.id===id);if(!o)throw Error('Pedido no encontrado. Actualiza los datos.');const owner=user?.id,run=generation;openOrder=id;openPanel=panel;
  const token=dialogs.open({key:'order',onClose:({discarded})=>{if(discarded)photos.drop(id);},title:`Pedido ${o.code}`,body:'<p role="status">Cargando pedido…</p>',wide:true,focus:'[data-dialog-close]'});
  const [events,past,payments]=await Promise.all([db.from('charito_order_history').select('*').eq('order_id',id).order('created_at',{ascending:false}).limit(100),db.from('charito_order_advances').select('*').eq('order_id',id).order('occurred_at'),db.rpc('charito_order_payments',{p_order:id})]);
  if(run!==generation||owner!==state().user?.id||!dialogs.is('order'))return;const error=events.error||past.error||payments.error;if(error){dialogs.update('order',`<div class="warn">${esc(error.message)}</div>`,token);return;}
  if(!dialogs.update('order',body(o,events.data||[],past.data||[],payments.data||[]),token))return;
  ctx.detailReady?.();dates.mount(dialogs.element);photos.mount(dialogs.element);selectPanel(panel);contextLabels();void photos.list(id,dialogs.element.querySelector('[data-order-saved-photos]'));
 }
 function contextLabels(){document.querySelectorAll('[data-form="new_order"],[data-form="order_payment"]').forEach(f=>{const target=f.querySelector('[data-payment-context]');if(!target)return;const value=f.elements.payment_date?.value||f.elements.occurred_at?.value,positive=f.dataset.form==='order_payment'?Number(f.elements.amount.value)>0:Number(f.elements.advance_cash.value)+Number(f.elements.advance_yape.value)>0;let label='';try{if(positive&&value&&paymentContext(value,state().shift,state().me.role).historical)label='Adelanto anterior · no modifica la caja de este turno.';}catch(e){if(positive&&value)label=e.message;}target.textContent=label;target.hidden=!label;});}
 async function submit(action,x,f){if(!['new_order','edit_order','cancel_order','order_payment','order_refund','deliver_order','upload_photos'].includes(action))return false;dates.validate(f);if(photos.preparing())throw Error('Espera a que terminen de prepararse las fotos.');const {data,shift,storeId,user,me}=state(),owner=user?.id,run=generation;let a=action,p={...x,id:f.dataset.id,shift_id:shift?.id},result,id=f.dataset.id;
  if(action==='new_order'){const code=String(x.code||'').trim();if(!code||code.length>80)throw Error('El código del pedido es obligatorio y admite hasta 80 caracteres.');const total=Number(x.total),cash=Number(x.advance_cash),yape=Number(x.advance_yape);if(!Number.isFinite(total)||total<0||!Number.isFinite(cash)||!Number.isFinite(yape)||cash<0||yape<0||Math.round((cash+yape)*100)>Math.round(total*100))throw Error('Revisa el precio y los adelantos del pedido.');const payments=[];if(cash>0||yape>0){const c=paymentContext(x.payment_date,shift,me.role);for(const [method,amount]of [['cash',cash],['yape',yape]])if(amount>0)payments.push({method,amount,occurred_at:c.occurred,historical:c.historical,reason:c.historical?`Adelanto anterior registrado al crear el pedido ${code}`:undefined});}
   p={store_id:storeId,shift_id:shift?.id,code,customer_name:x.customer_name,customer_phone:x.customer_phone,total,description:x.description,due_at:toIsoPeru(x.due_at),payments};
  }else if(action==='edit_order')p={...x,id,version:Number(f.dataset.version),total:Number(x.total),due_at:toIsoPeru(x.due_at)};
  else if(action==='cancel_order')p={id,version:Number(f.dataset.version),reason:x.reason};
  else if(action==='order_payment'){const c=paymentContext(x.occurred_at,shift,me.role);a=c.historical?'historical_advance':'order_payment';p={id,shift_id:shift?.id,amount:Number(x.amount),method:x.method,occurred_at:c.occurred,reason:c.historical?'Adelanto anterior registrado con su fecha real':'Pago de pedido'};}
  else if(action==='order_refund')p={id,shift_id:shift?.id,amount:Number(x.amount),method:x.method,reason:x.reason};
  else if(action==='deliver_order'){p={id,shift_id:shift?.id};if(x.product_id){p.product_id=x.product_id;p.qty=Number(x.qty);}}
  if(action==='upload_photos'){if(!photos.count(id))throw Error('Elige una foto antes de guardar.');await photos.upload(id);if(owner!==state().user?.id||run!==generation)return true;dialogs.clean();await detail(id,'photos');notice('Fotos guardadas.');return true;}
  result=await ctx.operate(a,p,f);if(owner!==state().user?.id||run!==generation)return true;
  let photoError='';if(action==='new_order'){id=result.id;photos.transfer('new',id);if(photos.count(id))try{await photos.upload(id);}catch(error){photoError=error.message;}}
  if(owner!==state().user?.id||run!==generation)return true;dialogs.close(true);ctx.flush();await ctx.load();if(owner!==state().user?.id||run!==generation)return true;ctx.render();
  if(action==='new_order'){await detail(id,photoError?'photos':'data');notice(photoError?'Pedido guardado. Quedan fotos pendientes; pulsa Guardar fotos pendientes para reintentar.':'Pedido guardado.',!!photoError);}else{await detail(id,action==='order_payment'||action==='order_refund'?'payments':action==='deliver_order'?'history':'data');notice('Pedido actualizado.');}return true;
 }
 async function click(b){if(b.hasAttribute('data-order-new')){openNew();return true;}if(photos.click(b))return true;if(b.dataset.orderDetail){await detail(b.dataset.orderDetail);return true;}if(b.hasAttribute('data-order-panel')){selectPanel(b.dataset.orderPanel);return true;}if(b.dataset.quickOrder){const panel={order_payment:'payments',deliver_order:'delivery',upload_photos:'photos'}[b.dataset.section]||'data';await detail(b.dataset.quickOrder,panel);return true;}return false;}
 async function input(e){if(await photos.input(e))return true;if(e.target.closest('[data-form="new_order"],[data-form="order_payment"]'))contextLabels();return false;}
 function mount(){photos.mount();dates.mount();contextLabels();}
 function clear(){generation++;openOrder=null;photos.clear();}
 return {orders,detail,submit,click,input,mount,clear,photoCount:key=>photos.count(key)};
}
